"""Entity identity: ``dat_id`` (UUIDv7, generated by the client).

Layout (RFC 9562, section 5.7), most significant bit first::

    unix_ts_ms (48) | ver = 0b0111 (4) | counter (12) | var = 0b10 (2) | random (62)

The 12-bit field is a counter (RFC 9562, section 6.2, method 1), so ids made by
one generator are strictly increasing even within one millisecond or when the
wall clock steps back. Each new millisecond seeds the counter with 11 random
bits, leaving at least 2048 values before it overflows; on overflow the
timestamp moves one millisecond ahead of the wall clock.
"""

import secrets
import threading
import time
import uuid
from collections.abc import Callable

__all__ = ["IdGenerator", "is_uuid7", "new_id", "timestamp_ms"]

_MAX_MS = (1 << 48) - 1
_MAX_COUNTER = (1 << 12) - 1
_VERSION = 0x7
_VARIANT = 0b10


def _system_ms() -> int:
    return time.time_ns() // 1_000_000


class IdGenerator:
    """Thread-safe UUIDv7 source, monotonic within one instance."""

    def __init__(
        self,
        *,
        clock_ms: Callable[[], int] = _system_ms,
        randbits: Callable[[int], int] = secrets.randbits,
    ) -> None:
        self._clock_ms = clock_ms
        self._randbits = randbits
        self._lock = threading.Lock()
        self._last_ms = -1
        self._counter = 0

    def __call__(self) -> uuid.UUID:
        with self._lock:
            ms = self._clock_ms()
            if not 0 <= ms <= _MAX_MS:
                raise ValueError(f"clock value {ms} does not fit the 48-bit UUIDv7 timestamp")
            if ms > self._last_ms:
                self._last_ms = ms
                self._counter = self._randbits(11)
            elif self._counter < _MAX_COUNTER:
                self._counter += 1
            else:
                if self._last_ms == _MAX_MS:
                    raise ValueError("48-bit UUIDv7 timestamp exhausted")
                self._last_ms += 1
                self._counter = self._randbits(11)
            ms, counter = self._last_ms, self._counter
        value = (
            (ms << 80) | (_VERSION << 76) | (counter << 64) | (_VARIANT << 62) | self._randbits(62)
        )
        return uuid.UUID(int=value)


new_id = IdGenerator()
"""Process-wide generator for ``dat_id`` and ``dat_txn``."""


def is_uuid7(value: uuid.UUID) -> bool:
    """True for an RFC 9562 version 7 UUID."""
    return value.version == _VERSION and value.variant == uuid.RFC_4122


def timestamp_ms(value: uuid.UUID) -> int:
    """Unix time in milliseconds stored in a UUIDv7."""
    if not is_uuid7(value):
        raise ValueError(f"{value} is not a UUIDv7")
    return value.int >> 80
